package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import org.json.*;import java.util.*;
/** Blackboard tools live inside the school agent and reuse the app's WebView profile. */
final class BlackboardTools {
 final GoalChatUi chat;final GoalAgentActivity a;final Handler handler=new Handler(Looper.getMainLooper());Dialog dialog;WebView web;LinearLayout rows;TextView status;boolean closed,autoJoin;int token;String script,requestedMode="";final List<WebView> windows=new ArrayList<>();JSONArray candidates=new JSONArray();final Runnable pulse=new Runnable(){public void run(){if(closed)return;if(dialog.getWindow().getDecorView().hasWindowFocus()&&NubiApplication.foreground.get()==a)BlackboardTools.this.run("keepalive",null,false);handler.postDelayed(this,60000);}};
 BlackboardTools(GoalChatUi c){chat=c;a=c.a;}
 static boolean allowed(String url){try{Uri u=Uri.parse(url);String h=u.getHost();return SchoolSignIn.allowed(url)||("https".equals(u.getScheme())&&u.getUserInfo()==null&&(u.getPort()==-1||u.getPort()==443)&&("au-lti.bbcollab.com".equals(h)||"unist-kr.zoom.us".equals(h)));}catch(Exception e){return false;}}
 void request(String mode){requestedMode=mode;show();}
 void show(){show("https://blackboard.unist.ac.kr/ultra/course",false);}
 void show(String url,boolean scheduled){if(!allowed(url)){a.toast("지원하지 않는 강의 주소예요.");return;}autoJoin=scheduled;try{script=a.readAsset("blackboard_tools.js");}catch(Exception e){a.toast("Blackboard 도구를 읽지 못했어요.");return;}
  LinearLayout root=chat.box(NubiCompanionUi.WHITE,12);LinearLayout title=new LinearLayout(a);TextView head=a.txt("똑똑이 · Blackboard",20,NubiCompanionUi.INK,true);title.addView(head,new LinearLayout.LayoutParams(0,-2,1));Button close=a.button("닫기",false);close.setOnClickListener(v->dialog.dismiss());title.addView(close);root.addView(title);status=a.txt("포털에서 보관한 세션으로 연결하고 있어요.",12,NubiCompanionUi.MUTED,false);root.addView(status);
  HorizontalScrollView actions=new HorizontalScrollView(a);LinearLayout bar=new LinearLayout(a);actions.addView(bar);root.addView(actions);for(String[] choice:new String[][]{{"과목","status"},{"공지","notices"},{"과제 가져오기","calendar"},{"할 일","todo_list"},{"할 일 추가","add"},{"자료 모으기","materials"},{"다운로드","downloads"},{"강의 예약","schedules"},{"표시 이름","alias"},{"제출물 확인","attempt"}}){Button b=a.button(choice[0],false);b.setOnClickListener(v->{switch(choice[1]){case "add":editTodo(null);break;case "downloads":downloads();break;case "schedules":schedules();break;case "alias":alias();break;default:run(choice[1],null,true);}});bar.addView(b);}
  web=createWeb();root.addView(web,new LinearLayout.LayoutParams(-1,0,3));ScrollView sc=new ScrollView(a);rows=chat.box(NubiCompanionUi.PANEL,10);sc.addView(rows);root.addView(sc,new LinearLayout.LayoutParams(-1,0,2));dialog=new Dialog(a);dialog.setContentView(root);dialog.setOnDismissListener(d->{closed=true;token++;handler.removeCallbacksAndMessages(null);WebSessionPolicy.checkpoint();for(WebView w:windows){w.stopLoading();w.destroy();}});dialog.show();dialog.getWindow().setLayout(-1,-1);dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);web.loadUrl(url);handler.postDelayed(pulse,60000);
 }
 WebView createWeb(){WebView w=new WebView(a);windows.add(w);WebSessionPolicy.attach(w);w.getSettings().setJavaScriptEnabled(true);w.getSettings().setAllowFileAccess(false);w.getSettings().setAllowContentAccess(false);w.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);w.getSettings().setSupportMultipleWindows(true);w.getSettings().setJavaScriptCanOpenWindowsAutomatically(autoJoin);
  w.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return r.isForMainFrame()&&!allowed(r.getUrl().toString());}public void onPageFinished(WebView v,String u){if(closed)return;WebSessionPolicy.checkpoint();status.setText("연결 화면 · "+Uri.parse(u).getHost());if(u.startsWith("https://blackboard.unist.ac.kr/ultra/institution-page")){v.loadUrl("https://blackboard.unist.ac.kr/ultra/course");return;}if(u.startsWith("https://blackboard.unist.ac.kr/"))v.evaluateJavascript("(()=>{const b=document.getElementById('unist-portal-login');if(b&&b.getClientRects().length){b.click();return true;}return false;})()",raw->{});if(u.startsWith("https://unist-kr.zoom.us/")){String name=a.getSharedPreferences("nubi_bb_preferences",0).getString("displayName","");if(!name.isEmpty()){Uri parsed=Uri.parse(u);if(!name.equals(parsed.getQueryParameter("uname"))){String js="(()=>{const u=new URL(location.href);u.searchParams.set('uname',"+JSONObject.quote(name)+");location.replace(u.href)})()";v.evaluateJavascript(js,r->{});return;}}}if(!requestedMode.isEmpty()&&u.startsWith("https://blackboard.unist.ac.kr/ultra/")){String mode=requestedMode;requestedMode="";handler.postDelayed(()->run(mode,null,true),4000);}if(autoJoin&&u.startsWith("https://au-lti.bbcollab.com/"))handler.postDelayed(()->joinSingle(v),1500);}});
  w.setWebChromeClient(new WebChromeClient(){public boolean onCreateWindow(WebView view,boolean isDialog,boolean gesture,Message result){if(!gesture&&!autoJoin)return false;WebView child=createWeb();ViewGroup parent=(ViewGroup)web.getParent();int index=parent.indexOfChild(web);ViewGroup.LayoutParams params=web.getLayoutParams();parent.removeView(web);parent.addView(child,index,params);web=child;((WebView.WebViewTransport)result.obj).setWebView(child);result.sendToTarget();return true;}});return w;
 }
 void joinSingle(WebView v){if(closed)return;v.evaluateJavascript("(()=>{if(location.hostname!=='au-lti.bbcollab.com')return 'wrong origin';const choices=[...document.querySelectorAll('a,button,[role=button]')].filter(e=>e.getClientRects().length&&/^(Join session|Join Course Room|세션 참여|강의실 참여)$/i.test((e.innerText||e.getAttribute('aria-label')||'').trim()));if(choices.length===1){choices[0].click();return 'unique join control selected';}return '확인 가능한 참여 버튼 '+choices.length+'개 · 화면에서 선택 필요';})()",raw->{if(!closed)status.setText("강의 접속 · "+raw+" · 카메라·마이크는 직접 확인해 주세요.");});}
 void run(String mode,JSONObject args,boolean show){if(closed)return;try{JSONObject cmd=args==null?new JSONObject():new JSONObject(args.toString());cmd.put("mode",mode);int current=++token;String key="__nubiBB_"+UUID.randomUUID().toString().replace("-","");web.evaluateJavascript(script+";NubiBBTools.run("+cmd+").then(v=>window['"+key+"']=JSON.stringify(v)).catch(e=>window['"+key+"']=JSON.stringify({state:'failed',reason:String(e.message).slice(0,300)}));",r->poll(current,key,mode,show,0));if(show)status.setText("Blackboard에서 실제 응답을 읽고 있어요.");}catch(Exception e){status.setText("요청을 만들지 못했어요.");}}
 void poll(int current,String key,String mode,boolean show,int count){if(closed||current!=token)return;if(count>160){status.setText("응답 시간 초과 · 연결과 원문 화면을 확인해 주세요.");return;}web.evaluateJavascript("window['"+key+"']||null",raw->{if(closed||current!=token)return;if(raw==null||raw.equals("null")){handler.postDelayed(()->poll(current,key,mode,show,count+1),250);return;}try{String text=new JSONArray("["+raw+"]").getString(0);if(text.length()>750000)throw new Exception();JSONObject r=new JSONObject(text);web.evaluateJavascript("delete window['"+key+"']",v->{});if(show)render(mode,r);else if(r.optString("state").equals("failed"))status.setText("세션 확인 실패 · "+r.optString("reason"));}catch(Exception e){status.setText("Blackboard 응답을 읽지 못했어요.");}});}
 void render(String mode,JSONObject result){rows.removeAllViews();String state=result.optString("state");if(mode.equals("notices")&&result.optJSONArray("navigation")!=null){JSONArray nav=result.optJSONArray("navigation");for(int n=0;n<nav.length();n++){JSONObject link=nav.optJSONObject(n);if(link!=null&&allowed(link.optString("url")))button(link.optString("title","공지 원문 열기"),()->web.loadUrl(link.optString("url")));}}if(!state.equals("observed")&&!state.equals("saved")&&!state.equals("checked")){note(result.optString("reason",result.optString("scope","이 화면에서 확인할 수 없어요.")));status.setText("확인 필요 · "+state);return;}JSONArray items=result.optJSONArray(mode.equals("status")?"courses":"items");if(mode.equals("notices"))BlackboardNoticeMonitor.store(a,items);if(items==null){note(result.optString("text",result.optString("scope",result.toString())));return;}status.setText("실제 조회 · "+items.length()+"개 · "+result.optString("scope",""));if(mode.equals("materials")){candidates=items;button("확인한 자료 "+items.length()+"개 일괄 다운로드",()->confirmDownloads());}
  if(mode.equals("todo_save"))importTasks(items);if(mode.equals("todo_remove")&&result.has("removedId"))try(TaskStore t=new TaskStore(a)){t.getWritableDatabase().delete("tasks","source_run=? AND goal_id=?",new String[]{"bb-calendar:"+result.optString("removedId"),chat.goalId});}if(mode.equals("calendar")){importTasks(items);chat.history.put(chat.message("assistant","Blackboard 캘린더에서 실제 일정 "+items.length()+"개를 확인하고 내 학교 일정·할 일에 반영했어. 원래 날짜와 출처를 함께 보관했어."));chat.save();}
  for(int n=0;n<items.length();n++){JSONObject item=items.optJSONObject(n);if(item==null)continue;String title=item.optString("title",item.optString("name","자료"));if(mode.equals("notices")){note(title+"\n게시: "+item.optString("createdAt","원문 확인")+"\n"+item.optString("text"));if(allowed(item.optString("url")))button("공지 원문 열기",()->web.loadUrl(item.optString("url")));continue;}long deadline=item.optLong("deadline",0);note((item.optBoolean("done")?"✓ ":"")+title+(deadline>0?"\n"+new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.KOREA).format(new Date(deadline)):""));String url=item.optString("url");if(!url.isEmpty()&&allowed(url))button(mode.equals("status")?"강의 열기":"원문 열기",()->web.loadUrl(url));if(mode.equals("status")){String course=courseId(url);if(!course.isEmpty())button("이 강의 Collaborate 접속·예약",()->lectureOptions(title,course));}if(mode.startsWith("todo")||mode.equals("calendar")){button("수정·완료·삭제",()->todoOptions(item));}}
 }
 void importTasks(JSONArray items){try(TaskStore tasks=new TaskStore(a)){for(int n=0;n<items.length();n++){JSONObject item=items.optJSONObject(n);if(!"blackboard".equals(item.optString("source")))continue;String source="bb-calendar:"+item.optString("id");android.content.ContentValues v=new android.content.ContentValues();v.put("title",item.optString("title"));v.put("kind","일정");v.put("state",item.optBoolean("done")?"done":"pending");v.put("updated",System.currentTimeMillis());v.put("goal_id",chat.goalId);v.put("source_url",item.optString("url"));String at=java.time.Instant.ofEpochMilli(item.optLong("deadline")).toString();v.put("due",at);v.put("start_at",at);v.put("end_at",at);v.put("timezone",TimeZone.getDefault().getID());v.put("is_all_day",0);v.put("source_run",source);if(tasks.getWritableDatabase().update("tasks",v,"source_run=? AND goal_id=?",new String[]{source,chat.goalId})==0)tasks.getWritableDatabase().insertOrThrow("tasks",null,v);}}}
 static String courseId(String url){try{Uri u=Uri.parse(url);String id=u.getQueryParameter("course_id");if(id==null){java.util.regex.Matcher m=java.util.regex.Pattern.compile("/ultra/courses/([^/]+)").matcher(u.getPath());if(m.find())id=m.group(1);}return id!=null&&id.matches("[A-Za-z0-9_:-]{1,100}")?id:"";}catch(Exception e){return "";}}
 void editTodo(JSONObject old){LinearLayout box=chat.box(NubiCompanionUi.WHITE,16);EditText title=new EditText(a);title.setHint("할 일");if(old!=null)title.setText(old.optString("title"));box.addView(title);EditText date=new EditText(a);date.setHint("마감: yyyy-MM-dd HH:mm (선택)");if(old!=null&&old.optLong("deadline")>0)date.setText(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.KOREA).format(new Date(old.optLong("deadline"))));box.addView(date);AlertDialog d=new AlertDialog.Builder(a).setTitle(old==null?"내 할 일 추가":"할 일 수정").setView(box).setNegativeButton("취소",null).setPositiveButton("저장",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{try{JSONObject args=new JSONObject();if(old!=null)args.put("id",old.getString("id"));args.put("title",title.getText().toString());String value=date.getText().toString().trim();if(!value.isEmpty()){java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.KOREA);f.setLenient(false);args.put("deadline",f.parse(value).getTime());}else args.put("deadline",JSONObject.NULL);run("todo_save",args,true);d.dismiss();}catch(Exception error){date.setError("제목과 날짜 형식을 확인해 주세요.");}}));d.show();}
 void todoOptions(JSONObject item){new AlertDialog.Builder(a).setTitle(item.optString("title")).setItems(new String[]{"수정",item.optBoolean("done")?"다시 할 일로":"완료 표시","로컬 목록에서 삭제"},(d,w)->{if(w==0)editTodo(item);else try{JSONObject args=new JSONObject().put("id",item.getString("id"));if(w==1){args.put("title",item.optString("title")).put("deadline",item.opt("deadline")).put("done",!item.optBoolean("done"));run("todo_save",args,true);}else run("todo_remove",args,true);}catch(Exception e){a.toast("할 일을 수정하지 못했어요.");}}).show();}
 void confirmDownloads(){if(candidates.length()==0){a.toast("현재 자료 화면을 열고 자료 모으기를 눌러 주세요.");return;}final JSONArray snapshot;try{snapshot=new JSONArray(candidates.toString());}catch(Exception e){return;}new AlertDialog.Builder(a).setTitle(snapshot.length()+"개 자료 다운로드").setMessage("현재 확인한 같은 Blackboard 출처의 자료를 앱 내부에 저장해요. 파일당 50MiB, 전체 200MiB까지이며 실제 저장 결과를 따로 표시해요.").setNegativeButton("취소",null).setPositiveButton("다운로드",(d,w)->{BlackboardDownloads.start(a,snapshot,()->{if(!closed)downloads();});downloads();}).show();}
 void downloads(){rows.removeAllViews();try(CampusFlowStore s=new CampusFlowStore(a)){List<JSONObject> files=s.list("bb_downloads");if(files.isEmpty())note("다운로드한 자료가 없어요. 강의자료 화면에서 ‘자료 모으기’를 눌러 주세요.");for(JSONObject f:files){note(f.optString("name")+" · "+f.optString("state")+" "+f.optString("reason"));if(f.optString("state").equals("downloaded"))button("저장된 파일 열기",()->{String name=f.optString("filename");java.io.File local=new java.io.File(new java.io.File(a.getFilesDir(),"documents"),name);if(name.endsWith(".pdf"))CampusPdfPreview.show(a,Uri.parse("content://"+a.getPackageName()+".documents/"+name));else try{Uri uri=Uri.parse("content://"+a.getPackageName()+".documents/"+name);a.startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,a.getContentResolver().getType(uri)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){a.toast("파일을 열 앱이 필요해요. 자료는 앱 내부에 저장됐어요.");}});else if(f.optString("state").equals("queued"))button("이 다운로드 묶음 취소",()->{BlackboardDownloads.cancel(a,f.optString("batch"));a.toast("대기 중 다운로드를 취소했어요.");});}}}
 void lectureOptions(String title,String course){String url="https://blackboard.unist.ac.kr/webapps/collab-ultra/tool/collabultra/lti/launch?course_id="+Uri.encode(course);new AlertDialog.Builder(a).setTitle(title).setItems(new String[]{"Collaborate 지금 열기","매주 접속 예약"},(d,w)->{if(w==0){autoJoin=true;web.loadUrl(url);}else schedule(title,url);}).show();}
 void schedule(String title,String url){String[] days={"일요일","월요일","화요일","수요일","목요일","금요일","토요일"};new AlertDialog.Builder(a).setTitle("매주 무슨 요일에 접속할까요?").setItems(days,(d,day)->new TimePickerDialog(a,(v,h,m)->{try{JSONObject row=new JSONObject().put("goal_id",chat.goalId).put("title",title).put("url",url).put("weekday",day+1).put("hour",h).put("minute",m);BlackboardSchedule.save(a,row);if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},812);a.toast("예약했어요. 앱을 보는 중이면 접속하고, 백그라운드에서는 알림으로 안내해요. Android에 따라 실행이 늦어질 수 있어요.");schedules();}catch(Exception e){a.toast("접속 예약을 저장하지 못했어요.");}},9,0,true).show()).show();}
 void schedules(){rows.removeAllViews();note("앱 화면 사용 중에는 예약 강의로 이동해요. 백그라운드는 Android 제한에 따라 알림으로 안내하며 정시 실행을 보장하지 않아요.");try(CampusFlowStore s=new CampusFlowStore(a)){for(JSONObject row:s.list("bb_schedules")){note(row.optString("title")+" · "+new Date(row.optLong("nextAt")));button("예약 삭제",()->{BlackboardSchedule.remove(a,row.optString("id"));schedules();});}}}
 void alias(){EditText e=new EditText(a);e.setHint("예: 학번_이름 · Zoom 표시 이름");e.setText(a.getSharedPreferences("nubi_bb_preferences",0).getString("displayName",""));new AlertDialog.Builder(a).setTitle("강의 표시 이름").setView(e).setNegativeButton("취소",null).setPositiveButton("저장",(d,w)->{String name=e.getText().toString().trim();if(name.length()>80||name.matches(".*[\\r\\n].*")){a.toast("표시 이름은 80자 이내로 입력해 주세요.");return;}a.getSharedPreferences("nubi_bb_preferences",0).edit().putString("displayName",name).apply();a.toast("UNIST Zoom 링크를 열 때 이 이름을 사용해요.");}).show();}
 void note(String text){rows.addView(a.txt(text,14,NubiCompanionUi.INK,false),Ui.match(a,-2,10));}
 void button(String label,Runnable action){Button b=a.button(label,false);b.setOnClickListener(v->action.run());rows.addView(b,Ui.match(a,-2,4));}
}
